#!/usr/bin/env python3
"""Approved adaptive scale control and shared Sub/Dub-style scene selector."""
import base64
import hashlib
import runpy
from pathlib import Path
root = Path(__file__).resolve().parents[2]
canonical = root / "Gallery-current.html"
raw = canonical.read_bytes()
assert len(raw) == 6916337 and hashlib.sha256(raw).hexdigest() == "9076274807010997193fd513a9253f079d142c0985c749054d6455f982a92876"
builder = runpy.run_path(str(root / "tools/build-gallery.py"))
builder["check"]()
source = raw.decode("utf-8")
